b = [1 -0.5];
a = [1 0.5];
fprintf('2-norm: %.4f\n', filternorm(b, a, 2));
fprintf('inf-norm: %.4f\n', filternorm(b, a, inf));
fprintf('FIR 2-norm: %.4f\n', filternorm([1 2 1], 1));

filters = {[1 2 1], [1 2 2 1], [1 0 -1], [1 2 -2 -1]};
for k = 1:numel(filters)
  fprintf('%s is type %d\n', mat2str(filters{k}), firtype(filters{k}));
end

b = [1 1 1 1]/4;
[h, w] = freqz(b, 1, 5);
fprintf('%.3f ', w); fprintf('\n');
fprintf('%.3f ', abs(h)); fprintf('\n');

h = impz(1, [1 -0.5], 5);
s = stepz(1, [1 -0.5], 5);
disp(max(abs(cumsum(h) - s)) < 1e-12)

[hr, w, phi] = zerophase([1 2 1], 1, 3);
disp(round(hr.' * 1000) / 1000)
disp(round(phi.' * 1000) / 1000)

figure('Visible', 'off');
[hz, hp] = zplane([1 0 -1], [1 -1.6 0.64]);
disp(hz.XData)
disp(hp.XData)

t = (0:199)' / 200;
x = sin(2*pi*5*t) + sin(2*pi*60*t);
y = bandpass(x, [40 80], 200);
fprintf('RMS before: %.2f\n', sqrt(mean(x.^2)));
fprintf('RMS after: %.2f\n', sqrt(mean(y.^2)));

t = (0:199)' / 200;
x = sin(2*pi*5*t) + sin(2*pi*60*t);
y = bandstop(x, [40 80], 200);
fprintf('RMS before: %.2f\n', sqrt(mean(x.^2)));
fprintf('RMS after: %.2f\n', sqrt(mean(y.^2)));

t = (0:199)' / 200;
x = sin(2*pi*5*t) + sin(2*pi*60*t);
[y, d] = lowpass(x, 20, 200);
fprintf('RMS before: %.2f\n', sqrt(mean(x.^2)));
fprintf('RMS after: %.2f\n', sqrt(mean(y.^2)));
fprintf('Filter length: %d\n', numel(d.Coefficients));

t = (0:199)' / 200;
x = 3 + sin(2*pi*1*t) + sin(2*pi*60*t);
y = highpass(x, 20, 200);
fprintf('mean before: %.2f\n', mean(x));
fprintf('mean after: %.2f\n', mean(y));
fprintf('RMS after: %.2f\n', sqrt(mean(y.^2)));

x = [1 2 3 4 5 6 7 8];
b = [1 2 1] / 4;
y = fftfilt(b, x);
disp(y)
disp(max(abs(y - filter(b, 1, x))) < 1e-12)

x = zeros(1, 41);
x(21) = 1;
[b, a] = butter(2, 0.3);
[~, i1] = max(filter(b, a, x));
[~, i2] = max(filtfilt(b, a, x));
fprintf('input peak at %d\n', 21);
fprintf('filter peak at %d\n', i1);
fprintf('filtfilt peak at %d\n', i2);

b = [1 1];
a = [1 -0.5];
x = [1 2 3 4 5 6];
yfull = filter(b, a, x);
y1 = filter(b, a, x(1:3));
zi = filtic(b, a, y1(3), x(3));
y2 = filter(b, a, x(4:6), zi);
disp([y1 y2])
disp(max(abs([y1 y2] - yfull)) < 1e-12)

k = [0.5 0.3];
x = [1 0 0 0 0];
f = latcfilt(k, x);
y = latcfilt(k, 1, x);
disp(f)
disp(y)
disp(latc2tf(k))

b = [1 2];
a = [1 -0.5 -0.06];
[r, p, k] = residuez(b, a);
disp(round(r.' * 1e4) / 1e4)
disp(round(p.' * 1e4) / 1e4)
disp(isempty(k))
[b2, a2] = residuez(r, p, k);
disp(round(b2 * 1e4) / 1e4)
disp(round(a2 * 1e4) / 1e4)

[b, a] = butter(4, 0.2);
sos = tf2sos(b, a);
x = [1 zeros(1, 5)];
y = sosfilt(sos, x);
disp(round(y * 1e4) / 1e4)
disp(max(abs(y - filter(b, a, x))) < 1e-10)
